use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn analyze_compiler_layers (source_dir : & Path , n : usize , top_k : usize) -> Result < Vec < LayerOntology > > { let mut analyzer = LayerAnalyzer :: new () ; let mut file_count = 0 ; println ! ("🦀 Analyzing compiler layers with {}-grams..." , n) ; for entry in walkdir :: WalkDir :: new (source_dir) { let entry = entry ? ; if entry . file_type () . is_file () { if let Err (e) = analyzer . analyze_file (entry . path () , n) { eprintln ! ("Warning: Failed to analyze {:?}: {}" , entry . path () , e) ; } else { file_count += 1 ; if file_count % 1000 == 0 { println ! ("  Processed {} files..." , file_count) ; } } } } let layers = vec ! [CompilerLayer :: AST , CompilerLayer :: HIR , CompilerLayer :: MIR , CompilerLayer :: THIR , CompilerLayer :: Parser , CompilerLayer :: Resolve , CompilerLayer :: TypeCk , CompilerLayer :: Codegen , CompilerLayer :: Lint , CompilerLayer :: Macro ,] ; let mut ontologies = Vec :: new () ; for layer in & layers { let patterns = analyzer . get_layer_patterns (layer , top_k) ; let total_patterns = analyzer . patterns . iter () . filter (| ((l , _) , _) | l == layer) . count () ; if ! patterns . is_empty () { let mut cross_relations = Vec :: new () ; for other_layer in & layers { if other_layer != layer { let relations = analyzer . find_cross_layer_relations (layer , other_layer) ; cross_relations . extend (relations . into_iter () . take (3)) ; } } let coverage = if total_patterns > 0 { (patterns . iter () . map (| p | p . frequency) . sum :: < usize > () as f64 / analyzer . patterns . iter () . filter (| ((l , _) , (f , _)) | l == layer) . map (| (_ , (f , _)) | f) . sum :: < usize > () as f64) * 100.0 } else { 0.0 } ; ontologies . push (LayerOntology { layer : layer . clone () , ngram_size : n , top_patterns : patterns , total_patterns , coverage_percentage : coverage , cross_layer_relations : cross_relations , }) ; } } println ! ("✅ Analyzed {} files across {} compiler layers" , file_count , ontologies . len ()) ; Ok (ontologies) }